cssStarter:
:root{--accent:#ff6600;--primary:#2371ff;--ink:#151735;--dark:#1d284b;--body:#4f5168;--surface:#ffffff;--surface-alt:#f3f6f9;--line:#dfe4ea;--container:1280px;--gutter:32px;--section-y:120px}
body{font-family:'Saira Semi Condensed',sans-serif;font-size:16px;line-height:1.5;color:var(--body)}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0 90px}
.eyebrow{display:inline-flex;align-items:center;gap:10px;font-size:20px;font-weight:500;line-height:1.2;color:var(--accent);margin-bottom:20px}
.hero-title{font-size:80px;font-weight:700;line-height:1.12;text-transform:uppercase;color:var(--ink);margin-bottom:30px}
.hero-sub{font-size:30px;font-weight:500;line-height:1.12;margin-bottom:50px}
h2{font-size:60px;font-weight:600;line-height:1.08;color:var(--ink);margin:0}
h3{font-size:36px;font-weight:600;line-height:1.2}
h4{font-size:27px;font-weight:600;line-height:1.2;color:var(--ink)}
p{font-size:16px;font-weight:500;line-height:1.75}
.btn{display:inline-flex;align-items:center;height:60px;padding:0 45px;border-radius:50px;font-size:16px;font-weight:600;background:var(--accent);color:#fff}
.btn-primary{background:var(--primary)}
.btn-outline{background:transparent;border:1px solid #dce1e4;color:var(--ink);height:40px;padding:0 30px;font-weight:400}
.card{background:#fff;border:1px solid var(--line);border-radius:5px;padding:45px}
.input{height:60px;padding:0 20px;border-radius:3px;border:0;background:#fff;font-size:16px}
@media(max-width:768px){:root{--section-y:72px}.hero-title{font-size:44px}h2{font-size:38px}h3{font-size:26px}}
